{"path": "analysis.py", "content": "from collections import deque

def tile_of(K, x, y):
    # x=S_x etc integer, point (x+0.5,y+0.5)
    X = x + 0.5
    Y = y + 0.5
    # floor division for K>0
    import math
    i = math.floor(X / K)
    j = math.floor(Y / K)
    if (i & 1) == (j & 1): # same parity? Need check parity with Python negative numbers: parity of integer i (mathematical). Python's % yields 0 for even, 1 for odd? For negative numbers -1 %2 =1 in Python, which matches parity (odd). So use i%2
        # H
        k = math.floor(Y - j*K)  # floor
        # ensure 0<=k<K
    else:
        k = math.floor(X - i*K)
    return (i,j,k)

def neighbors(K, i,j,k):
    # return list of (i2,j2,k2)
    # determine orientation
    if (i % 2) == (j % 2): # H
        # interior
        if k > 0:
            yield (i,j,k-1)
        if k < K-1:
            yield (i,j,k+1)
        # west
        yield (i-1, j, K-1)
        # east
        yield (i+1, j, 0)
        # south/north fan
        if k == 0:
            for kp in range(K):
                yield (i, j-1, kp)
        if k == K-1:
            for kp in range(K):
                yield (i, j+1, kp)
    else: # V
        if k > 0:
            yield (i,j,k-1)
        if k < K-1:
            yield (i,j,k+1)
        # north
        yield (i, j+1, 0)
        # south
        yield (i, j-1, K-1)
        if k == 0:
            for kp in range(K):
                yield (i-1, j, kp)
        if k == K-1:
            for kp in range(K):
                yield (i+1, j, kp)

def bfs_distance(K, S, T):
    # S,T are (x,y) integer tile coordinates (S_x,S_y)
    start = tile_of(K, S[0], S[1])
    target = tile_of(K, T[0], T[1])
    if start == target:
        return 0
    # BFS limited
    # use deque
    visited = {start:0}
    dq = deque([start])
    while dq:
        cur = dq.popleft()
        d = visited[cur]
        for nb in neighbors(K, *cur):
            if nb not in visited:
                if nb == target:
                    return d+1
                visited[nb]=d+1
                dq.append(nb)
    return None

def test_examples():
    print("test 3,-2,1->4,-1", bfs_distance(3, (-2,1), (4,-1)))
    print("4,8,8->0,2", bfs_distance(4, (8,8), (0,2)))
    print("51,...", bfs_distance(51, (94,7), (-90,-34)))
    print("63...", bfs_distance(63, (-9,49), (-45,29)))
    # Additional checks from test file
    # Print tile ids
    for K,S,T in [(51,(94,7),(-90,-34)),(67,(24,3),(100,-23)),(63,(-9,49),(-45,29))]:
        print(K, tile_of(K,S[0],S[1]), tile_of(K,T[0],T[1]), bfs_distance(K,S,T))

if __name__ == "__main__":
    test_examples()
"}

