import math
from collections import deque

def tile_of(K, x, y):
    X = x + 0.5
    Y = y + 0.5
    i = math.floor(X / K)
    j = math.floor(Y / K)
    if (i % 2) == (j % 2):
        k = math.floor(Y - j*K)
    else:
        k = math.floor(X - i*K)
    return (i,j,k)

def neighbors(K, i,j,k):
    if (i % 2) == (j % 2): # H
        if k > 0:
            yield (i,j,k-1)
        if k < K-1:
            yield (i,j,k+1)
        # east/west any
        # east to V0
        yield (i+1, j, 0)
        # west to VK-1
        yield (i-1, j, K-1)
        if k == K-1:
            for kp in range(K):
                yield (i, j+1, kp)
        if k == 0:
            for kp in range(K):
                yield (i, j-1, kp)
    else: # V
        if k > 0:
            yield (i,j,k-1)
        if k < K-1:
            yield (i,j,k+1)
        yield (i, j+1, 0)
        yield (i, j-1, K-1)
        if k == K-1:
            for kp in range(K):
                yield (i+1, j, kp)
        if k == 0:
            for kp in range(K):
                yield (i-1, j, kp)

def bfs_dist(K, start, target):
    if start == target:
        return 0
    visited={start:0}
    dq=deque([start])
    while dq:
        cur=dq.popleft()
        d=visited[cur]
        for nb in neighbors(K,*cur):
            if nb not in visited:
                if nb==target:
                    return d+1
                visited[nb]=d+1
                dq.append(nb)
    return None

def bfs_block_any(K):
    # compute D between blocks up to range
    # map block (i,j) -> set of tiles = {(i,j,k) for k}
    # distance between any tile in block A to any tile in block B is min over k,k' distance
    # BFS from any tile in source block (multi-source)
    def block_dist(si,sj,ti,tj):
        sources = [(si,sj,k) for k in range(K)]
        # Actually need to consider if block is H/V determines? but k range same
        visited={}
        dq=deque()
        for s in sources:
            visited[s]=0
            dq.append(s)
        while dq:
            cur=dq.popleft()
            d=visited[cur]
            if cur[0]==ti and cur[1]==tj:
                return d
            for nb in neighbors(K,*cur):
                if nb not in visited:
                    visited[nb]=d+1
                    dq.append(nb)
        return None
    return block_dist

def test_debug():
    K=3
    bd=bfs_block_any(K)
    rows=[]
    for di in range(-3,4):
        for dj in range(-3,4):
            si,sj=0,0
            ti,tj=di,dj
            d=bd(si,sj,ti,tj)
            rows.append(f"({di},{dj})={d}")
    assert False, " ".join(rows)

