    return (i,j,k)

def neighbors(K,i,j,k):
    if (i%2)==(j%2):
        if k>0: yield (i,j,k-1)
        if k<K-1: yield (i,j,k+1)
        yield (i+1,j,0)
        yield (i-1,j,K-1)
        if k==K-1:
            for kp in range(K):
                yield (i,j+1,kp)
        if k==0:
            for kp in range(K):
                yield (i,j-1,kp)
    else:
        if k>0: yield (i,j,k-1)
        if k<K-1: yield (i,j,k+1)
        yield (i,j+1,0)
        yield (i,j-1,K-1)
        if k==K-1:
            for kp in range(K):
                yield (i+1,j,kp)
        if k==0:
            for kp in range(K):
                yield (i-1,j,kp)

def rect(K,i,j,k):
    if (i%2)==(j%2):
        return (i*K, (i+1)*K, j*K+k, j*K+k+1)
    else:
        return (i*K+k, i*K+k+1, j*K, (j+1)*K)

def adjacent(a,b):
    x0a,x1a,y0a,y1a = a
    x0b,x1b,y0b,y1b = b
    if x1a==x0b or x1b==x0a:
        if min(y1a,y1b)-max(y0a,y0b) > 0:
            return True
    if y1a==y0b or y1b==y0a:
        if min(x1a,x1b)-max(x0a,x0b) > 0:
            return True
    return False

def neighbors_brute(K,i,j,k):
    r0=rect(K,i,j,k)
    res=[]
    for di in [-2,-1,0,1,2]:
        for dj in [-2,-1,0,1,2]:
            ii=i+di; jj=j+dj
            for kk in range(K):
                if di==0 and dj==0 and kk==k:
                    continue
                r1=rect(K,ii,jj,kk)
                if adjacent(r0,r1):
                    res.append((ii,jj,kk))
    return set(res)

